	public static <T> List<T> listTail(List<T> list, int startIndex) {
		if (startIndex == 0) {
			return list;
		}
		int size = list.size();
		if (startIndex >= size) {
			return Collections.emptyList();
		}
		return list.subList(startIndex, size);
	}

